/* FILE: kb-admin.js  (GitHub par isi naam se upload karein) */
/* A2Z Sahayak ki admin wali jankari. Isme koi password / OTP / SETUP_CODE / token nahi hai. Ye file sirf admin.html par load hoti hai. */
(function () {
  'use strict';
  if (!window.A2ZHelp) return;
  var A = ['admin'];
  window.A2ZHelp.add([
    { id: 'a-setup', a: A, cat: 'Shuruaat', title: 'Admin pehli baar kaise banayein (setup)?', kw: ['setup', 'pehli baar', 'admin banana', 'naya admin', 'shuru', 'start', 'admin account', 'setup code', 'first time'],
      where: 'admin.html (pehli baar kholne par "Pehli baar setup")', steps: ['GitHub wali website me /admin.html kholein. Pehli baar "Pehli baar setup" form dikhega.', 'Setup code wo likhein jo aapne Apps Script ke Script Properties me rakha hai (ye code sirf aapko pata hona chahiye).', 'Admin ka user naam, majboot password (12+ akshar) aur apna Gmail likhein, phir submit karein.', 'Ab login page aayega. Setup sirf ek baar hota hai.'], tip: 'Setup code, password aur Gmail kisi ko na batayein, chat me bhi nahi likhein. Poori jankari guide ke Part C me hai.', rel: ['a-login'] },
    { id: 'a-login', a: A, cat: 'Shuruaat', title: 'Admin login aur OTP kaise chalta hai?', kw: ['login', 'otp', 'admin login', 'sign in', 'gmail otp', 'email otp', 'otp nahi aaya', 'otp kaise', 'andar jana', 'verification'],
      where: 'admin.html', steps: ['admin.html kholein, user naam aur password likhein, submit karein.', 'Aapke Gmail par 6 ank ka OTP aayega. "OTP daalein" screen me wo likhein.', 'Sahi OTP par dashboard khul jayega. Upar tab dikhenge: Overview, Approvals, Party / Company, Staff aur links, Candidates, Hazri (Daily), Payouts, Hisaab (aaya/gaya), Owners ka hissa, Reminder, Settings.'], tip: 'OTP na aaye to Gmail ka Spam / Promotions dekhein, "Peeche" dabakar dobara login karein. Bahut baar galat likhne par kuch der ke liye lock lag jata hai. OTP kisi ko na batayein.', rel: ['a-otp-email'] },
    { id: 'a-otp-email', a: A, cat: 'Shuruaat', title: 'OTP ki email ya admin password kaise badlein?', kw: ['otp email', 'email badalna', 'gmail badalna', 'password badalna', 'admin password', 'password change', 'password badlein', 'naya password', 'nayi email'],
      where: 'Settings tab', steps: ['"Settings" tab kholein.', '"Password badlein" me purana aur naya password likhein, save karein.', '"OTP ki email badlein" me "Nayi email" likhein aur save karein.'], tip: 'Admin password bhool gaye hon to guide ke Part F ("bhoolne par") me tareeka likha hai.' },
    { id: 'a-party', a: A, cat: 'Party aur rate', title: 'Nayi party (company) aur uska rate card kaise banayein?', kw: ['party', 'company', 'nayi party', 'party jodna', 'party add', 'rate card', 'rate', 'trade rate', 'mistri rate', 'helper rate', 'party banana', 'client', 'company banana', 'rate set'],
      where: 'Party / Company tab', steps: ['"Party / Company" tab kholein.', '"+ Nayi party" dabayein.', 'Party ka naam, phone, email, contact person, pata, GSTIN bharein.', 'Rate card me "+" se line jodein: Trade (jaise Mason), Company rate (company se kitna milega) aur Candidate rate (candidate ko kitna dena hai). Per-din mode me ye rate rupaye/din hote hain (mistri 1000, helper 330 jaise).', '"Save" dabayein.', 'Baad me badalne ke liye party ki card me "Edit / Rate card" dabayein.'], tip: 'Admin ka tay kiya rate staff bina approval nahi badal sakta. Settings me "Rate kaise tay hote hain" me per-din ya mahine wala tareeka chunein.', rel: ['a-perday', 'a-rate-approve'] },
    { id: 'a-perday', a: A, cat: 'Party aur rate', title: 'Per-din rate aur mahine ke rate me kya fark hai? Kaise badlein?', kw: ['per din', 'per day', 'perday', 'din ka rate', 'mahine ka rate', 'monthly', 'daily rate', 'rate kaise tay', '26 din', 'basis'],
      where: 'Settings tab -> "Rate kaise tay hote hain"', steps: ['"Settings" tab kholein.', '"Rate kaise tay hote hain" me chuniye: "Per-din rate" (mistri 1000/din) ya "Mahine ka rate (÷ mahine ke din)".', 'Save karein. Hisaab naye tareeke se bante hain.'], tip: 'Naya version per-din par chalta hai. Purane mahine wale rate (jaise 20,000/mahina) ho to ya unhe per-din me dobara bharein ya yahan se mahine wala tareeka chunein.' },
    { id: 'a-staff-add', a: A, cat: 'Staff', title: 'Naya staff / supplier kaise jodein aur uska link / password kaise dein?', kw: ['staff', 'naya staff', 'staff jodna', 'staff add', 'supplier', 'manpower supplier', 'staff banana', 'staff link', 'link', 'staff password', 'commission %', 'staff ka login', 'agent', 'supervisor'],
      where: 'Staff aur links tab', steps: ['"Staff aur links" tab kholein.', '"+ Naya staff" dabayein. Naam, mobile, prakar (Staff / Manpower supplier / Site supervisor) aur "Commission ka tareeka" (percent / fixed rate / koi hissa nahi) chunkar save karein.', 'Staff ke card me "Password set" se uska login password set karein, ya use kahein ki wo staff page par "Naya staff registration" se khud registration kare.', 'Staff ka seedha link "Link copy" se copy karke ya WhatsApp se bhej sakte hain. "Naya link (purana band)" se puraana link band hota hai.', 'Staff ka ID card "ID card" button se nikalta hai.'], tip: 'Staff apne ID ya mobile aur password se login karta hai. Site supervisor ki fixed payment staff edit me "Fixed payment" me bharein.', rel: ['a-staff-approve'] },
    { id: 'a-staff-approve', a: A, cat: 'Staff', title: 'Staff ki registration approve kaise karein?', kw: ['approve', 'approval', 'staff approve', 'registration', 'naya staff registration', 'registration approve', 'staff ki manjoori', 'serial', 'staff id', 'staff ko id dena', 'reject'],
      where: 'Approvals tab -> "Naye staff ki registration"', steps: ['"Approvals" tab kholein (tab ke naam ke aage pending ginti dikhti hai).', '"Naye staff ki registration" me staff ki jankari aur photo dekhein ("photo dekhein" se).', '"Prakar" chuniye (Staff ya Manpower supplier).', '"Commission ka tareeka" zaroor chuniye: 1 Percent, 2 Fixed rate (trade-wise), 3 Koi hissa nahi. Bina chune approve nahi hota.', '"Approve karein" dabayein. Turant Staff ID (A2Z-S-xxxx) ban jati hai aur staff login kar sakta hai.', 'Galat ya shak wali registration ho to "Reject" dabayein.'], tip: 'Approve karne se pehle Aadhaar / bank ki jankari aur mobile number dhyan se jaanch lein.', rel: ['a-approvals'] },
    { id: 'a-comm-options', a: A, cat: 'Staff', title: 'Manpower supplier ka commission kaise tay karein? (percent / fixed rate / koi hissa nahi)', kw: ['commission', 'commission option', 'commission ka tareeka', 'fixed rate', 'trade wise rate', 'grade wise rate', 'fitter ka rate', 'welder ka rate', 'helper ka rate', '40 percent', 'percent commission', 'supplier ka hissa', 'manpower supplier ka hissa', 'koi hissa nahi', 'direct candidate', 'supplier ka rate'],
      where: 'Staff aur links tab -> Staff edit, ya Approvals tab', steps: ['Staff banate ya approve karte samay "Commission ka tareeka" chuniye. Bina chune aage kaam nahi chalta.', '1 Percent: pool ka X% (jaise 40%). Hisaab me supplier ka naam aur uske candidate kin party me hain wo bhi dikhta hai.', '2 Fixed rate: har trade ka rate likhein (jaise Fitter 200, Welder 150, Helper 100 per din). Candidate kitne bhi hon rate wahi rahta hai. Jo trade likha nahi uska commission 0 aur warning aayegi.', '3 Koi hissa nahi: us staff ko kuch nahi banta, poora hissa firm ka.', 'Jab koi supplier ho hi nahi (aapne khud candidate bheje), to candidate me "Staff" khali rakhein. Koi hissa nahi banta, rate aur agreement admin hi tay karta hai.'], tip: 'Purane staff jinka option abhi tay nahi hai unka commission 0 dikhta hai aur warning aati hai. Unka Staff edit kholkar option chun lein.', rel: ['a-staff-approve', 'a-money'] },
    { id: 'a-update-msg', a: A, cat: 'Setup', title: '"Naya update aaya hai" message kya hai? Update kaise karein?', kw: ['update', 'naya update', 'update aaya', 'update message', 'app update', 'version', 'update kaise kare', 'abhi update karein', 'purana version', 'update hua ya nahi'],
      where: 'Admin, Staff aur main website, sabhi par neeche', steps: ['Jab aap GitHub par nayi files upload karte hain, phone ya browser me app khulte hi neeche hari patti aati hai: "Naya update aaya hai".', '"Abhi update karein" dabayein. Page apne-aap naye version me khul jata hai.', '"Baad me" dabane par patti hat jati hai, agli baar phir aayegi.', 'Neeche kone me chhota version number (jaise v8) dikhta hai. Naya update lene ke baad ye badal jata hai.'], tip: 'Upload ke baad kuch minute lagte hain (GitHub Pages ko). Patti na aaye to app band karke dubara kholein.', rel: [] },
    { id: 'a-photo-doc', a: A, cat: 'Candidate', title: 'Photo / document 100 KB me kaise karein? Crop aur edit kaise karein?', kw: ['photo', 'document', 'aadhaar', 'passbook', '100 kb', 'size', 'crop', 'edit photo', 'photo chhoti', 'photo badi', 'rotate', 'ghumana', 'roshni', 'file size', 'upload'],
      where: 'Candidate / Staff form me "Photo chunein" ya Documents ke khane', steps: ['"Photo chunein" ya document ke khane me "Chunein" dabayein aur phone se photo lein ya file chunein.', 'Edit screen khulegi: photo ko khichkar sahi jagah layein, Zoom se crop karein, Ghumayein se seedha karein, Roshni / Contrast theek karein. Frame me Photo ya Document (A4) chun sakte hain.', 'Neeche live dikhega ki file ka size kitna hoga. "Save" dabate hi file apne-aap 100 KB ke andar ho jati hai.', 'Documents ke 4 khane hain: Aadhaar (aage), Aadhaar (peeche), Bank passbook / cheque, Anya.', 'Save ke baad "Dekhein" se document dobara khol sakte hain; "Badlein" se naya laga sakte hain.'], tip: 'Server bhi 100 KB se badi file mana kar deta hai, isliye badi file kabhi save nahi hoti.', rel: [] },
    { id: 'a-supplier-sites', a: A, cat: 'Staff', title: 'Manpower supplier ke candidate kaun si site me hain? Alag Excel kahan milegi?', kw: ['supplier', 'supplier report', 'site wise', 'kitne candidate', 'supplier ke candidate', 'supplier code', 'supplier excel', 'manpower supplier ka hisaab', 'kaun si site', 'party wise supplier'],
      where: 'Admin -> "Supplier (Site-wise)" tab', steps: ['"Supplier (Site-wise)" tab kholein. Upar har supplier ka code, naam, kitne candidate kaam par, kitni site, din aur commission dikhta hai.', 'Neeche har supplier ke liye site (party) wise table hai: kis site me kaun se trade ke kitne candidate.', '"Candidate-wise list" kholkar har candidate ka code, naam, site, din aur commission dekh sakte hain.', '"Sab suppliers ki Excel" se sabka, ya supplier ke saamne "Excel" se sirf uska hisaab download hota hai (sheets: Supplier, Site-wise, Candidates).'], tip: 'Supplier ko vetan nahi milta, sirf commission. Candidate ki list me ab supplier ka naam aur code saath me aata hai.', rel: ['a-comm-options'] },
    { id: 'a-terms', a: A, cat: 'Setup', title: 'Terms & Conditions (niyam aur shartein) kahan hain? Sahmati kaise lete hain?', kw: ['terms', 'terms and conditions', 'niyam', 'shartein', 'sahmati', 'consent', 'labour law', 'kanoon', 'agreement', 'objection', 'dpdp', 'data consent'],
      where: 'Website ke neeche "Terms" link (terms.html); registration / candidate form me tick', steps: ['Website ke neeche "Terms / नियम और शर्तें" par dabayein: Hindi + English me, candidate, supplier / staff, client party aur data-consent ki shartein.', 'Staff registration aur naya candidate bharte samay "Terms padh liye aur sahmat hu" ka tick zaroori hai. Bina tick ke save nahi hota.', 'Tick ki tareekh aur version record me save hota hai (candidate edit me "Darj" dikhta hai).'], tip: 'Ye saamanya jankari hai, kanooni salah nahi. Final agreement par sign karne se pehle kisi vakil / labour salahkar se zaroor dikhwa lein.', rel: [] },
    { id: 'a-party-where', a: A, cat: 'Party aur rate', title: 'Banai hui party aur uski details kahan dekhein?', kw: ['party kahan dikhegi', 'party dekhna', 'party details', 'party ki jankari', 'party list', 'party kaha dekhe', 'banai hui party', 'party ki id', 'party ka hisaab'],
      where: 'Admin -> "Party / Company" tab', steps: ['Admin kholein aur upar ki tab-patti me "Party / Company" dabayein. Yahan sabhi parties ek ke neeche ek card me dikhti hain (sabse nayi neeche).', 'Har card par party ka naam, contact / phone, Baaki ya "Poora mila", trade-wise candidate aur Company bill, Commission, Milna chahiye, Mil chuka, Baaki dikhta hai.', '"Candidates dekhein" dabane par us party ke saare candidate (naam, mobile, trade, staff, din, wage) khulte hain.', '"Edit / Rate card" se party ki details aur rate badalein; "Payment mila" se company ka payment likhein; "Reminder" aur "Excel" bhi usi card me hain.', 'Party ki ID (jaise A2Z-P-001) dekhni ho to "ID dekhein" tab me party ka naam ya ID likhein.'], tip: 'Party sirf Admin banata hai. Staff ko party ka naam sirf candidate jodte waqt list me dikhta hai.' },
    { id: 'a-find-id', a: A, cat: 'Setup', title: 'ID dekhein: staff, candidate aur party / company ki ID', kw: ['id dekhein', 'serial number', 'id kaise dekhe', 'id dhundhna', 'mobile se id', 'naam se id', 'kisi ki id'],
      where: 'Admin ya Staff panel -> "ID dekhein" tab', steps: ['"ID dekhein" tab kholein.', 'Box me mobile number (kam se kam 3 ank), naam ya ID likhein. ID chhoti bhi likh sakte hain, jaise a2z-s-1.', 'Neeche turant list aa jati hai: Prakar, ID, Naam, Mobile aur jankari (trade, party, supplier).', 'Admin me staff, candidate aur party / company sabki ID dikhti hai (Staff: A2Z-S-0001, Candidate: A2Z-C-00001, Party: A2Z-P-001). Staff panel me apni aur apne candidates ki ID dikhti hai.'], tip: 'Naya staff / candidate / party banate hi chhoti "Ho gaya" screen me uski ID, naam aur mobile aa jata hai; "Details copy karein" se bhej sakte hain.', rel: [] },
    { id: 'a-stay-login', a: A, cat: 'Setup', title: 'Baar-baar login kyu maangta tha? Ab kab tak login rahega?', kw: ['baar baar login', 'password baar baar', 'login hat jata hai', 'refresh par login', 'khud logout', 'login kab tak'],
      where: 'Admin aur Staff dono', steps: ['Ek baar login karne ke baad refresh karne, naya tab kholne ya mobile band-khol karne par login bana rehta hai.', 'Login tabhi khatam hota hai jab aap "Logout" dabate hain (ya 90 din baad, ya password badalne par).', 'Computer aur mobile dono par alag-alag login chal sakte hain.'], tip: 'Dusre ke computer ya mobile par kaam karke hamesha "Logout" dabayein. Mobile kho jaye to Suraksha tab se "Sab admin session band" karein.', rel: [] },
    { id: 'a-approvals', a: A, cat: 'Staff', title: 'Approvals tab me kya-kya approve hota hai?', kw: ['approvals', 'approval', 'manjoori', 'pending', 'sab approval', 'kya baaki', 'staff approval', 'candidate approval', 'hazri approval', 'rate request'],
      where: 'Approvals tab', steps: ['Naye staff ki registration (Approve karein / Reject).', 'Candidate approval: staff ke jode candidate (staff khud bhi approve karta hai; aap bhi kar sakte hain).', 'Hazri approval: staff ki bhari hazri. "Approve" ya "Sab approve karein".', 'Rate badalne ki request: "Manjoor" ya "Mana" (reject).', 'Jab tak approve na ho, staff ki hazri admin ke final hisaab me nahi judti.'] },
    { id: 'a-cand-admin', a: A, cat: 'Candidate', title: 'Candidate admission form kahan se milega / candidate kaise jodein?', kw: ['admission form', 'admission', 'candidate form', 'naya candidate', 'candidate jodna', 'candidate add', 'majdoor', 'worker', 'labour', 'candidate banana', 'candidate ki jankari', 'photo'],
      where: 'Candidates tab', steps: ['"Candidates" tab kholein.', '"+ Naya candidate" dabayein.', 'Naam, mobile, trade, party, staff (ya "Direct"), joining date bharein; photo "Photo chunein" se lagayein.', 'Pita ka naam, janm tithi, pata, Aadhaar, bank, emergency number, anubhav jaisi poori jankari bharein.', 'Rate khali chhodenge to party ke rate card se apne-aap lagega. Alag rate dena ho to "Candidate rate" me likhein.', '"Save" dabayein. Candidate ko serial number (A2Z-C-xxxxx) mil jata hai.'], tip: 'Staff apne candidate khud admission form se jodta hai; wo aapko "Approvals" me dikhta hai. Candidate approve hone ke baad hi hazri / hisaab me aata hai.', rel: ['a-serial'] },
    { id: 'a-serial', a: A, cat: 'Candidate', title: 'Serial number se candidate kaise dhoondhein?', kw: ['serial', 'serial number', 'khojna', 'search', 'dhoondhna', 'pata lagana', 'kaun hai', 'candidate dhoondhna', 'id'],
      where: 'Candidates tab ka "Khojein" box', steps: ['"Candidates" tab kholein.', '"Khojein (naam, mobile, trade, serial)" box me serial (jaise A2Z-C-00012), naam ya mobile likhein.', 'List me wahi candidate dikhega. Party ya staff ke hisaab se chhaantne ke liye upar "Party" aur "Staff" wale box bhi hain.', 'Row me "ID card" se uska ID card nikal sakte hain.'] },
    { id: 'a-work', a: A, cat: 'Hazri aur paisa', title: 'Daily Kaam (roz ka kaam + labour + munafa) kaise dekhein?', kw: ['daily kaam', 'daily work', 'roz ka kaam', 'kaam ka hisaab', 'labour', 'munafa', 'profit', 'civil', 'mechanical', 'jagah', 'site', 'team', 'naap', 'm3', 'party wise kaam', 'kaam theek hai', 'sudhar'],
      where: 'Daily Kaam tab', steps: ['Pehli baar "Daily Kaam" tab ke neeche "Civil + Mechanical ki shuruaati list bhar dein" dabayein, phir har kaam aur labour ka rate bharein (kaam ka per ikai rate, labour ka roz ka rate).', 'Staff roz ka kaam aur kitne labour lage wo likhta hai. Rate, keemat aur munafa staff ko nahi dikhte.', 'Aaj ka kaam = aaj tak ka kul naap - kal tak ka kul naap (jaise 17 - 15 = 2 m3). Kaam ki keemat = kaam x rate; labour kharch = har labour ki ginti x uska rate; munafa = keemat - kharch.', 'Party-wise, jagah-wise, team-wise aur din-wise jod neeche dikhta hai. Entry kholkar badal sakte hain aur "Theek hai / Sudhar karein" jawab likh sakte hain, jo staff ko dikhta hai.', '"Party ko bhejein" se us party ko email jata hai. "Excel" se company format me file banti hai.'], tip: 'Kisi party ka rate alag ho to "Party / Company" me us party ka Edit kholkar "Daily Kaam: is party ke kaam ke rate" me likhein.', rel: ['a-party-comm'] },
    { id: 'a-party-comm', a: A, cat: 'Hazri aur paisa', title: 'Party ka commission kis staff ko jaye ye kaise tay karein?', kw: ['commission kisko', 'party commission', 'commission anak', 'commission sukhendra', 'commission ram', 'commission jaye', 'commission nahi', 'party wise commission', 'commission set'],
      where: 'Party / Company tab > Edit / Rate card', steps: ['Party card par "Edit / Rate card" dabayein.', '"Is party ka commission kise jaye?" me "Sirf neeche chune hue staff ko" chuniye aur jin staff ko dena hai unhe tick karein.', 'Kisi ko tick na karein to us party ka commission kisi staff ko nahi jayega.', 'Save karein. Party card par "Commission jata hai: ..." dikhega.'], tip: 'Jab tak ye tay nahi karte, purana tarika chalta hai (sabko jata hai) aur Overview par chetavani dikhti hai.', rel: ['a-work'] },
    { id: 'a-office-staff', a: A, cat: 'Staff', title: 'Office staff aur site staff me fark kaise karein? Office staff ki salary?', kw: ['office staff', 'office wala staff', 'office time', 'site staff', 'jagah ka staff', 'subah 9 se shaam 6', 'bina commission staff', 'salary'],
      where: 'Staff aur links > + Naya staff', steps: ['"+ Naya staff" me Prakar me "Office staff (09:00 am - 06:00 pm, commission nahi)" chunein; commission wala hissa chhup jata hai.', 'Fixed payment me uski mahine ki salary likhein aur "Salary kaise banegi" chunein.', 'Staff ki list me har staff ke naam ke saath "Office staff" ya "Site / Jagah ka staff" ka nishan dikhta hai.', 'Office staff ke panel me sirf Duty, hisaab aur ID dikhte hain. Wo bhi selfie se IN / OUT karta hai.'], tip: 'Office staff ko kisi party ka commission nahi milta.', rel: ['a-duty-salary'] },
    { id: 'a-duty-salary', a: A, cat: 'Hazri aur paisa', title: 'Staff ki salary duty ke din ke hisaab se kaise banti hai? Salary Excel kahan se?', kw: ['staff salary', 'salary din ke hisaab', 'duty ke din salary', '25000 salary', 'salary excel', 'per din salary', 'tankhwah', 'aadha din', '9 ghante'],
      where: 'Duty / Location tab', steps: ['Staff me "Salary kaise banegi" = "Duty ke din ke hisaab se" chunein. Salary = poore mahine ki salary / 26 x duty ke din.', 'Duty ki ginti: 9 ghante baad OUT (15 min chhoot) = 1 din; 4.5 ghante se upar = aadha din; usse kam = 0.', 'Staff bina location ke bhi IN kar sakta hai (selfie zaruri). Galat ginti ho to Duty list me "Ginti" se badal dein.', '"Duty / Location" tab ke "Excel" me Staff salary, Din-wise ginti aur Duty register milte hain.'], tip: 'Staff ko apni salary apne Duty tab me dikhti hai.', rel: ['a-duty'] },
    { id: 'a-enquiry', a: A, cat: 'Website', title: 'Website se enquiry kahan dikhegi? Kisne aur kahan se bheji?', kw: ['enquiry', 'enquiry kahan', 'quote request', 'contact form', 'website se customer', 'inquiry', 'naya customer'],
      where: 'Enquiry tab', steps: ['Website ke Contact form se jo bhi bhejta hai wo seedha admin ke "Enquiry" tab me aata hai (naam, mobile, kaam, details, samay).', 'Naya aane par aapki email par bhi khabar aati hai.', 'Phone / WhatsApp ke link se baat karein, phir Halat "Baat hui" ya "Ho gaya" chunein aur note likhein.', 'Faltu / spam ko "Spam" chunein ya "Hatayein" dabayein. "Excel" se list download hoti hai.'], tip: 'Yahan sirf naam aur mobile aate hain, shahar ka pata nahi chalta; isliye details me "site kahan hai" likhwane ka form hai.', rel: [] },
    { id: 'a-web-rates', a: A, cat: 'Website', title: 'Website par dikhne wale labour aur material ke rate kaise badlein?', kw: ['website ke rate', 'manpower rate', 'labour rate website', 'index page rate', 'material rate badlein', 'rate kaise badlega', 'calculator rate', 'public rate'],
      where: 'Website ke rate tab', steps: ['"Website ke rate" tab kholein. Pehli baar "Website ki list yahan laayein" dabayein.', 'Kisi bhi trade / material ka rate, naam ya "Dikhayein" badlein; "+ Labour / trade" ya "+ Material" se naya jodein.', '"Save karein (sabko dikhega)" dabayein. Website kholte hi sabko naya rate dikhta hai.'], tip: 'Ye public website ke rate hain. Party ke rate (jis par bill banta hai) alag hain: Party / Company > Edit / Rate card.', rel: ['a-party-category'] },
    { id: 'a-party-category', a: A, cat: 'Party / Company', title: 'Ek party civil aur mechanical dono kaam de to alag rate kaise rakhein?', kw: ['civil aur mechanical', 'dono kaam', 'alag rate party', 'party ka rate alag', 'doosra kaam', 'company ka doosra kaam', 'sany civil', 'har party alag rate'],
      where: 'Party / Company', steps: ['Party ki entry me "Kaam ka prakar" (Civil / Mechanical) chunein aur company ka naam likhein.', 'Usi company ka doosra kaam ho to party card par "Isi company ka doosra kaam" dabayein: naye form me jankari bhari milti hai, prakar ulta ho jata hai.', 'Har entry me kaam ka tarika (labour+commission ya naap), labour rate aur "is party ke kaam ke rate" alag likhein: jaise Sany 15 aur Shivkripa 24 per sqft.', 'Kisi kaam ka party-wise rate khali ho to list ka sab party wala rate lagta hai aur Overview par chetavani aati hai.'], tip: 'Staff Daily Kaam me Civil party par Mechanical kaam nahi likh sakta.', rel: ['a-web-rates'] },
    { id: 'a-pw-forgot', a: A, cat: 'Suraksha', title: 'Staff ya admin apna password bhool jaye to kya karein?', kw: ['password bhool', 'password bhul', 'password reset', 'password badlein', 'login nahi ho raha', 'otp nahi aaya', 'naya password', 'temporary password'],
      where: 'Approvals / Apps Script', steps: ['STAFF: login page par apna ID likhkar "Password bhool gaye?" dabata hai. Admin ke Approvals me "Password bhoolne ki request" dikhti hai (email bhi aati hai). "Naya password set karein" dabakar password banayein aur staff ko phone par batayein.', 'ADMIN: Apps Script editor me function a2zAdminTempPassword chalayein. Naya temporary password sirf admin ki registered email par jata hai. Us se login karke Settings me apna password badal lein.', 'Admin ka password Script Properties me dekha nahi ja sakta (wo chhupa hua hash hai) aur dekhna theek bhi nahi.'], tip: 'Agar admin ki email hi band ho jaye to a2zResetAdmin chalakar naya admin banayein; sheet ka data safe rehta hai.', rel: [] },
    { id: 'a-duty', a: A, cat: 'Hazri aur paisa', title: 'Staff kahan hai? Duty IN / OUT, selfie aur location kaise dekhein?', kw: ['duty', 'in out', 'location', 'staff kahan hai', 'selfie', 'gps', 'map', 'attendance staff', 'staff ki attendance', 'live location', 'track'],
      where: 'Duty / Location tab', steps: ['"Duty / Location" tab kholein. Upar "Abhi ki sthiti" me har staff ki halat dikhti hai: duty par / aaj nahi aaya.', 'Duty par staff ki aakhri location ka samay aur "Map dekhein" link dikhta hai. Location tabhi aati hai jab staff ka app khula ho; purani ho to laal chetavani aati hai.', '"IN selfie" dabakar staff ki selfie dekhein. Neeche poori list me IN / OUT dono selfie aur IN se OUT ki doori dikhti hai.', 'Staff OUT karna bhool jaye to "Duty band karein" dabayein aur chunein ki us din ki attendance ginni hai ya nahi.', '"Excel" se mahine ki duty aur staff-wise attendance company format me milti hai.'], tip: 'Attendance tabhi judti hai jab staff OUT kare. OUT ke baad uski location dikhna band ho jata hai.', rel: ['a-advance-staff'] },
    { id: 'a-advance-staff', a: A, cat: 'Hazri aur paisa', title: 'Staff ne labour ko jo advance diya wo kahan dikhta hai?', kw: ['staff ne advance diya', 'labour ko advance', 'mistri ko advance', 'advance kata', 'advance minus', 'staff ne diya'],
      where: 'Hisaab tab > Advance', steps: ['Staff apne panel ke "Mera hisaab" me "+ Labour / candidate ko advance dein" se entry karta hai.', 'Aapke "Hisaab (aaya/gaya)" tab ki Advance list me wo entry dikhti hai.', 'Advance us mahine ke candidate ke "Dena baaki" se kat jata hai, isliye mahine ke ant ki payment utni kam banti hai.', 'Galat entry ho to aap "Hatayein" se hata sakte hain; staff sirf apni aaj ki entry hata sakta hai.'], tip: 'Staff ko advance dena ho to Hisaab tab me "Staff ko advance" wala form pehle jaisa hi hai.', rel: ['a-duty'] },
    { id: 'a-party-model', a: A, cat: 'Party', title: 'Party kis tarah kaam deti hai (labour + commission ya naap ka kaam) kaise tay karein?', kw: ['kaam ka tarika', 'party ka tarika', 'party model', 'labour commission', 'naap ka kaam', 'wazan', 'length', 'measurement', 'party payment tay', 'labour payment kaun tay', 'party kaise kaam deti hai', 'bill kaise banega'],
      where: 'Party / Company > Edit / Rate card > "Ye party kis tarah kaam deti hai?"', steps: ['Party card par "Edit / Rate card" dabayein aur "Kaam ka tarika" chuniye.', '1) Labour hamse leti hai aur hume commission deti hai: labour ki payment party tay karti hai. Rate card me "Candidate ko" = party ki tay ki hui payment, "Hamara commission" = hume milne wala (rupaye ya % me). Party ka bill apne-aap payment + commission banta hai.', '2) Naap / wazan / length ka kaam: labour ki payment hum tay karte hain ("Candidate ko"). Party ko bill kaam ki keemat se banta hai: Daily Kaam ka naap x party ka rate (isi panel me neeche). Hazri se party ka bill nahi banta.', 'Save karein. Party card par tarika dikhega aur staff ko bhi (rate ke bina).'], tip: 'Ek hi party dono tarah ka kaam deti ho to use do naam se (jaise "Sany - Labour" aur "Sany - Kaam") banayein.', rel: ['a-work', 'a-party-comm'] },
    { id: 'a-master', a: A, cat: 'Overview', title: 'Poora Dashboard: shuru se aaj tak sab entry ek jagah kaise dekhein?', kw: ['poora dashboard', 'dashboard', 'sab entry', 'sab kuch ek jagah', 'shuru se aaj tak', 'kul jod', 'total', 'mahine wise', 'poori website', 'sab ka hisaab', 'sab entries'],
      where: 'Poora Dashboard tab (Overview ke baad)', steps: ['"Poora Dashboard" tab kholein. Upar shuru se aaj tak ka kul jod dikhta hai: bill, labour payment, margin, staff commission, owners ka munafa, party se mila / baaki, advance, Daily Kaam.', 'Neeche graph aur mahine-wise hisaab ki table hai.', 'Sabse neeche "Sab entry" me party, staff, candidate, hazri, advance, payment, party se mila, kharch, Daily Kaam, duty, request, reminder aur admin log ki entry naye se purani dikhti hai.', 'Prakar ke button se ek tarah ki entry chunein, "Khojein" me naam / party / rakam likhein, aur Tarikh se-tak se samay chunein.', '"Excel (sab)" se kul jod, mahine-wise aur chuni hui sab entries company format me milti hain.'], tip: 'Ye sirf dekhne ke liye hai. Kuch badalna ho to us entry wale tab me jayein. Aadhaar, bank, password jaisi nijji jaankari yahan nahi aati.', rel: [] },
    { id: 'a-hazri', a: A, cat: 'Hazri aur paisa', title: 'Roz ki hazri (attendance) kaise bharein?', kw: ['hazri', 'attendance', 'haziri', 'present', 'daily', 'roz', 'din', 'hazri bharna', 'attendance sheet', 'party wise hazri', 'live hisaab', 'turant hisaab', 'sheet'],
      where: 'Hazri (Daily) tab', steps: ['"Hazri (Daily)" tab kholein, upar mahina aur "Party" chuniye.', 'Tarikh (1-31) dabane se us din sab hazir; candidate ke dibbe par dabane se P (poora), ½ (aadha), · (gair-hazir).', 'Neeche har din ki ginti aur turant candidate wage, staff ka commission, GST aur teeno owners (Anak, Shukhendra, Ram) ka hissa tak poori kadi dikhti hai.', '"Hazri save karein" dabayein.', 'Excel ke liye "Excel (is party ki)" ya "Excel (sab party)" button hai.'], tip: 'Admin ki bhari hazri turant approved hoti hai. Staff ki hazri Approvals me aapke approve karne par judti hai.', rel: ['a-hazri-approve'] },
    { id: 'a-hazri-approve', a: A, cat: 'Hazri aur paisa', title: 'Staff ki hazri approve kaise karein?', kw: ['hazri approve', 'attendance approve', 'hazri approval', 'staff ki hazri', 'sab approve', 'approve hazri', 'hazri manjoor'],
      where: 'Approvals tab -> "Hazri approval"', steps: ['"Approvals" tab kholein.', '"Hazri approval" table me candidate, party, staff aur din dekhein (purane approved din bhi dikhte hain).', 'Sahi lage to "Approve", warna "Reject". Sab ek saath ho to "Sab approve karein".'], tip: 'Approve hote hi wo hazri Payouts, Owners ka hissa aur Hisaab me judti hai.' },
    { id: 'a-rate-approve', a: A, cat: 'Party aur rate', title: 'Staff ki rate badalne ki request kaise manjoor karein?', kw: ['rate request', 'rate badalna', 'rate change', 'rate approve', 'rate manjoor', 'naya rate', 'rate badhana'],
      where: 'Approvals tab -> "Rate badalne ki request"', steps: ['"Approvals" tab kholein.', '"Rate badalne ki request" table me abhi ka rate, maanga gaya rate aur karan dekhein.', '"Manjoor" dabane par naya rate lag jata hai; "Mana" dabane par purana rate hi rehta hai.'], tip: 'Bina aapke approval ke koi bhi rate nahi badalta.' },
    { id: 'a-advance', a: A, cat: 'Paisa', title: 'Advance kaise darj karein?', kw: ['advance', 'adhim', 'udhaar', 'advance dena', 'advance entry', 'pehle diya'],
      where: 'Hisaab (aaya/gaya) tab -> "+ Advance"', steps: ['"Hisaab (aaya/gaya)" tab kholein, upar sahi mahina chuniye.', '"+ Advance" dabayein.', '"Kisko" me staff ya candidate chuniye, rakam, tarikh aur note likhein.', 'Save karein. Staff ke "Baaki milna" aur candidate ke "Dena baaki" se ye rakam ghat jati hai.', 'Galat entry ho to neeche Advance table me "Hatayein" dabayein.'] },
    { id: 'a-paid', a: A, cat: 'Paisa', title: 'Kise kitna paisa chukaya gaya - paid-tracking kaise karein?', kw: ['chukaya', 'paid', 'payment diya', 'paisa diya', 'kise kitna', 'kitna diya', 'baaki', 'payment record', 'paid tracking', 'gaya', 'jana', 'kisko diya', 'payment chukaya', 'payment chukaya darj', 'chukaya darj', 'owners ko diya', 'candidate ko diya', 'staff ko diya', 'cash', 'upi', 'bank transfer'],
      where: 'Hisaab (aaya/gaya) tab -> "Kise kitna chukaya gaya"', steps: ['"Hisaab (aaya/gaya)" tab kholein, mahina chuniye.', '"Kise kitna chukaya gaya" table me har staff, candidate aur owner ke saamne dikhta hai: dena tha (advance ghatne ke baad), chukaya, baaki.', 'Paisa dene par us row me "Chukaya" dabayein.', 'Kitna diya (baaki wali rakam pehle se bhari hoti hai), tarikh, "Kaise diya" (Cash / UPI / Bank / Anya) aur note (jaise UPI ref no.) likhkar "Payment save karein" dabayein.', 'Row me "Baaki" ghat jata hai; poora dene par "Poora chukaya" likha aata hai.', 'Neeche "Chukaye gaye payments" me har payment ki list hai; galti ho to "Hatayein".', 'Upar cards me "Chukaya (kul)" aur "Chukana baaki" dikhta hai. "Sab kuch Excel me" me "Chukaya (paid)" aur "Payment record" sheet bhi aati hai.'], tip: 'Baaki se zyada rakam save nahi hoti. Staff ko apne aur apne candidates ke payment "Mera hisaab" me dikhte hain.', rel: ['a-advance', 'a-money'] },
    { id: 'a-money', a: A, cat: 'Paisa', title: 'Kul kitna paisa aaya aur kitna gaya (party-wise / staff-wise)?', kw: ['aaya gaya', 'aaya', 'gaya', 'kitna aaya', 'kitna gaya', 'party wise', 'staff wise', 'party-wise', 'staff-wise', 'total paisa', 'hisaab', 'company me kya ho raha', 'commission party wise', 'party ka commission', 'party payment details', 'kul'],
      where: 'Hisaab (aaya/gaya) tab', steps: ['"Hisaab (aaya/gaya)" tab kholein aur mahina chuniye.', 'Upar cards: companies se aana, aa chuka, abhi aana baaki, advance, kharch, chukaya, chukana baaki.', '"Jo paisa aayega wo kahan jayega": candidates ka wage, staff ka commission, GST, supervisor, office salary, anya kharch aur teeno owners me bachi rakam. Neeche note batata hai ki aana-jana barabar hai ya nahi.', '"Party-wise paisa aur commission" me har party ka bill, company commission, wage, margin, pool, staff commission, firm ka hissa, aana, aaya aur baaki dikhta hai.', '"Staff-wise" me har staff ki party-wise detail, commission, GST, net, advance aur baaki dena dikhta hai.', 'Poora Excel "Sab kuch Excel me" se milta hai.'], rel: ['a-paid', 'a-owners'] },
    { id: 'a-owners', a: A, cat: 'Paisa', title: 'Teeno owners (Anak, Shukhendra, Ram) ka hissa kaise banta hai?', kw: ['owners', 'owner', 'anak', 'shukhendra', 'ram', 'hissa', 'baantna', 'barabar', 'munafa', 'profit', 'pool', 'commission', 'gst', '40', 'distributable', 'firm ka hissa'],
      where: 'Owners ka hissa tab', steps: ['Company ka bill = rate x din. Company ka commission (default 5%) bill par jodta hai.', 'Margin (company rate - candidate rate) + company commission = Pool.', 'Pool ka 40% (settings se badal sakte hain) staff / supplier ka commission; usme se 18% GST katta hai.', 'Baaki firm ka hissa; usme firm ka GST, supervisor ki fixed payment, office salary aur anya kharch ghatane ke baad jo bache wo teeno owners me barabar baant jata hai.', '"Owners ka hissa" tab me ye poori kadi aur har owner ki rakam dikhti hai. "+ Kharch" se office / anya kharch jodein.'], tip: 'Commission, GST aur barabar bantwara wali maanyataayein apne CA se confirm karwa lein.' },
    { id: 'a-expense', a: A, cat: 'Paisa', title: 'Office salary ya anya kharch kaise jodein?', kw: ['kharch', 'kharcha', 'expense', 'office salary', 'salary', 'anya kharch', 'bijli', 'kiraya', 'rent', 'office', 'kharch jodna'],
      where: 'Owners ka hissa tab -> "+ Kharch"', steps: ['"Owners ka hissa" tab kholein.', '"Is mahine ke kharch" me "+ Kharch" dabayein.', 'Prakar (office salary ya anya), vivaran aur rakam likhkar save karein.', 'Ye kharch teeno owners ke hisse se pehle ghatta hai.'] },
    { id: 'a-receipt', a: A, cat: 'Paisa', title: 'Company se payment mila - kaise darj karein?', kw: ['payment mila', 'receipt', 'company ne diya', 'party ne diya', 'paisa aaya', 'payment aaya', 'received', 'jama', 'baaki payment'],
      where: 'Party / Company tab -> party card me "Payment mila"', steps: ['"Party / Company" tab kholein.', 'Us party ke card me "Payment mila" dabayein.', 'Rakam, tarikh aur note likhkar save karein.', 'Party ka "Aaya" aur "Baaki" turant badal jata hai. Poora milne par "Poora mila" dikhta hai.'] },
    { id: 'a-remind', a: A, cat: 'Paisa', title: 'Company ko payment ka reminder kaise bhejein?', kw: ['reminder', 'yaad dilana', 'payment late', 'baaki payment', 'whatsapp', 'email bhejna', 'phone kiya', 'tagada', 'due'],
      where: 'Reminder tab (ya Overview ke "Payment late (company)" me "Reminder")', steps: ['"Reminder" tab kholein. Jin party ka paisa baaki / late hai wo dikhti hain.', 'Party ke saamne "Reminder" dabayein; Hindi-English ka taiyar message khulega.', '"WhatsApp se bhejein" se WhatsApp me ya "Email bhejein" se company ki email par bhej sakte hain; phone par baat ki ho to "Phone kiya (note karein)".', 'Bheja gaya reminder list me darj ho jata hai.'] },
    { id: 'a-excel', a: A, cat: 'Excel aur backup', title: 'Excel me download kaise karein?', kw: ['excel', 'download', 'xlsx', 'file', 'sheet', 'export', 'nikalna', 'report', 'spreadsheet'],
      steps: ['Har tab me "Excel" button hota hai: Party / Company, Staff aur links, Candidates, Owners ka hissa, Hazri (is party ki / sab party).', 'Sabse poori file ke liye Hisaab (aaya/gaya), Overview ya Payouts me "Sab kuch Excel me" dabayein: ek file me kai sheet (hazri, party-wise, staff-wise, aaya-gaya, chukaya, owners ka hissa, kharch...).', 'File apne phone / computer me download hoti hai.'] },
    { id: 'a-backup', a: A, cat: 'Excel aur backup', title: 'Backup kaise lein?', kw: ['backup', 'surakshit', 'data safe', 'copy', 'data khona', 'data chala gaya', 'save'],
      where: 'Settings tab -> Backup', steps: ['"Settings" tab kholein.', '"Backup" me "Backup download" dabayein. Poora data ek file me aa jata hai.', 'Har hafte download karke surakshit jagah rakhein. Google Sheet ki bhi kabhi-kabhi copy bana lein.'], tip: 'Backup file me Aadhaar / bank jaisi jankari hoti hai; use kisi ko na bhejein.' },
    { id: 'a-settings', a: A, cat: 'Settings', title: 'Commission %, GST % aur dusri settings kahan badlein?', kw: ['settings', 'setting', 'commission', 'commission percent', 'gst', 'gst percent', 'bonus', '5%', 'company ka commission', 'payment ke din', 'mahine ke din'],
      where: 'Settings tab', steps: ['"Settings" tab kholein.', 'Yahan hain: Staff / supplier commission %, staff ke commission par GST %, company jo commission deti hai (% of bill), rate kaise tay hote hain (per-din / mahina), firm ke hisse par GST %, company ko payment ke din, hissa (barabar = sabke liye 1).', 'Badalkar Save karein. Party ya staff ke andar alag value bhi rakh sakte hain.'], tip: 'Settings badalne se hisaab turant naye tareeke se ban jata hai.' },
    { id: 'a-idcard', a: A, cat: 'Candidate', title: 'Staff / candidate ka ID card kaise nikalein?', kw: ['id card', 'card', 'pehchan patra', 'serial', 'photo card', 'print', 'id banana'],
      steps: ['Staff ka: "Staff aur links" me uske card me "ID card".', 'Candidate ka: "Candidates" tab me uski row me "ID card".', '"PNG download" ya "Print" dabayein.'], tip: 'Photo ho tabhi card me photo aati hai (staff / candidate ki photo "Photo dekhein" se dekh sakte hain).' },
    { id: 'a-month', a: A, cat: 'Hazri aur paisa', title: 'Dusre mahine ka hisaab kaise dekhein?', kw: ['mahina', 'month', 'pichla', 'purana', 'agla', 'tarikh', 'date'],
      steps: ['Upar "Mahina" box me mahina chuniye.', 'Sab tab (hazri, payouts, hisaab, owners) us mahine ke ho jate hain.'] },
    { id: 'a-delete', a: A, cat: 'Settings', title: 'Entry hatani ho ya band karni ho to?', kw: ['delete', 'hatana', 'hatayein', 'mita', 'band karna', 'inactive', 'staff hatana', 'party hatana', 'galti se bhara'],
      steps: ['Advance, payment, kharch jaisi entry ke saamne "Hatayein" hota hai.', 'Jis party me candidates ya payments hon use hata nahi sakte; party / staff ko "Edit" me "active" band kar dein.', 'Candidate ko hatane par uski hazri aur advance bhi hat jati hai; hatane se pehle backup le lein.'] },
    { id: 'a-update', a: A, cat: 'Nayi file lagana', title: 'Nayi files kaise lagayein (Apps Script / GitHub)?', kw: ['update', 'nayi file', 'deploy', 'naya version', 'apps script', 'github', 'upload', 'file badalna', 'code', 'paste', 'a2zcheckfiles', 'version'],
      steps: ['Apps Script me har .gs file kholein, purana sab hatayein (Ctrl+A, Delete), nayi file ka poora code paste karein. Kul 8 .gs file hain.', '"a2zCheckFiles" chalayein - "Sab theek" aana chahiye.', 'Deploy -> Manage deployments -> Edit -> "New version" -> Deploy.', 'GitHub par web folder ki saari files (Ctrl+A) dobara upload karein.', 'Browser me page refresh karein (Ctrl+F5).'], tip: 'Poora vivaran guide ke Part F aur H me hai.' },
    { id: 'a-security', a: A, cat: 'Surakshit rakhna', title: 'Website aur data surakshit kaise rakhein?', kw: ['security', 'surakshit', 'safe', 'suraksha', 'chori', 'hack', 'gupt', 'secret', 'private', 'sheet private', 'github par data'],
      steps: ['Admin password, Gmail aur SETUP_CODE kisi ko na batayein.', 'GitHub (public) par sirf website ki files hoti hain; koi data ya password wahan nahi dalte.', 'Google Sheet ko private rakhein; use kisi se share na karein (usme Aadhaar / bank ki jankari hoti hai).', 'Kaam ke baad "Logout" karein; kisi aur ke device par login na rakhein.', 'Har hafte backup lein.'] },
    { id: 'a-error', a: A, cat: 'Samasya', title: 'Error aa raha hai / "Server se connect nahi ho pa raha"', kw: ['error', 'galti', 'server', 'connect', 'nahi khul', 'kaam nahi kar raha', 'atak', 'slow', 'dikkat', 'samasya', 'problem', 'nahi chal raha'],
      steps: ['Internet check karein aur page refresh karein.', 'Apps Script Deploy me "Who has access: Anyone" hona chahiye aur naya version deploy hona chahiye.', 'web ki config.js me Apps Script ka sahi link paste hona chahiye.', 'Apps Script me a2zCheckFiles chalakar dekhein ki saari 8 file sahi lagi hain.', 'Phir bhi na chale to screen ka photo lekar madad lein.'] },
    { id: 'a-staff-panel', a: A, cat: 'Staff', title: 'Staff panel me staff ko kya dikhta hai?', kw: ['staff panel', 'staff kya dekhta', 'staff ka panel', 'staff dekh sakta', 'staff ka hisaab', 'shubham', 'jay ambe', 'staff view'],
      steps: ['Staff apni ID / mobile aur password se login karta hai.', 'Use sirf apna data dikhta hai: Meri profile / ID (ID card), Candidates (admission form), Hazri (Daily) aur Mera hisaab (party-wise, advance, payment).', 'Staff ko owners ka hissa, company ka margin ya dusre staff ka data nahi dikhta.', 'Staff ki hazri aur rate request aapke approval par hi final hoti hain.'] },
    { id: 'a-pw-eye', a: A, cat: 'Suraksha', title: 'Password dikhane wali aankh (eye) aur SETUP_CODE apne aap kyon hat jata hai?', kw: ['eye', 'aankh', 'password dikhana', 'password dekhna', 'password chhupana', 'show password', 'setup code', 'setup_code', 'setup code hat gaya', 'setup code gayab', 'setup code delete'],
      where: 'Har password wale khane ke daayein kone me', steps: ['Password ke khane ke daayein kone ki aankh dabayein to likha hua password dikhta hai; dobara dabane par chhup jata hai. Ye admin, staff aur main website sab jagah hai.', 'Password 20 second baad ya form bhejte hi apne-aap dobara chhup jata hai.', 'SETUP_CODE sirf ek baar ke liye hai: admin ka setup poora hote hi server use apne-aap hata deta hai. Ye bilkul theek hai aur suraksha ke liye hai.', 'Dobara setup chahiye (jaise password bhool gaye) to a2zResetAdmin chalayein, phir Script Properties me naya SETUP_CODE daalein.'], tip: 'Aankh dabane se pehle dekh lein ki aapke aas-paas koi aapki screen to nahi dekh raha.' },
    { id: 'a-sec-what', a: A, cat: 'Suraksha', title: 'Suraksha (Alert) kya hai aur kaise kaam karta hai?', kw: ['suraksha', 'security', 'alert', 'surakshit', 'nigrani', 'chhedkhani', 'chhedchhad', 'khatra', 'suraksha alert', 'security alert', 'kaun badal raha'],
      where: 'Admin me "Suraksha (Alert)" tab', steps: ['Website par koi galat login, chhedkhani, data me anjaan badlav, Sheet ya website ki file me badlav ho to server turant alert banata hai.', 'Alert aapki Gmail par email aata hai (phone par Gmail app ka notification) aur Suraksha tab me lal number dikhta hai.', 'Har alert ke saath "Abhi kya karein" ke steps aur emergency button hote hain.', 'Dekh lene ke baad "Dekh liya" dabayein. Sab alerts ek Excel me bhi download ho sakte hain.'], tip: 'Alert me kabhi koi password ya OTP nahi hota. Gambhir alert ka rang lal aur "TURANT KARO" likha hota hai.', rel: ['a-sec-attack', 'a-sec-install'] },
    { id: 'a-sec-attack', a: A, cat: 'Suraksha', title: 'Koi chhedkhani / hack kar raha ho to abhi kya karein?', kw: ['hack', 'hack ho gaya', 'chhedkhani', 'koi kar raha', 'koi badal raha', 'chori', 'data chori', 'attack', 'abhi kya karein', 'kya karu', 'samapt', 'rokna', 'bachao', 'band karna', 'khatra'],
      where: 'Suraksha (Alert) tab', steps: ['Shaant rahein aur Suraksha tab kholein; jo alert lal ho uske "Abhi kya karein" steps ek-ek karke karein.', 'Sabse pehle Settings me admin password badlein (12+ akshar, akshar aur ank) aur Gmail ka password bhi badlein.', 'Suraksha tab me "Sab admin session band karein" dabayein (dobara dabane par pakka hota hai); phir apna login karein.', 'Staff par shak ho to "Staff panel abhi band karein" dabayein; baad me "Sab staff session band" karke staff ko naya login dilwayein.', 'Google Sheet kholkar File -> Version history se dekhein kisne kab badla; galat ho to purana version restore karein. Drive ke "A2Z Backups" me roz ki copy hai.', 'Sab shant hone par "Staff panel dobara kholein" dabayein.'], tip: 'Pehle ye jaanchein ki kahin aapne ya aapke saathi ne hi to galti se nahi kiya. Aksar galat password ka alert wahi hota hai.', rel: ['a-sec-sheet', 'a-sec-site'] },
    { id: 'a-sec-sheet', a: A, cat: 'Suraksha', title: 'Google Sheet me kisi ne badlav kiya ya share kar diya to?', kw: ['sheet badli', 'sheet me badlav', 'sheet edit', 'google sheet', 'sheet share', 'sheet shared', 'version history', 'sheet restore', 'data badal gaya', 'sheet ka alert', 'drive'],
      where: 'Suraksha tab aur Google Sheet', steps: ['Har ghante website Sheet ki antim badlav ki samay-sima dekhti hai. App ke bahar (seedha Sheet me) badlav ho to "Google Sheet app ke bahar badli gayi" alert aata hai.', 'Sheet kholkar File -> Version history -> See version history me dekhein ki kisne badla (naam dikhta hai).', 'Share button me dekhein; sirf aap hone chahiye aur "General access" Restricted hona chahiye.', 'Galat badlav ho to purana version restore karein.'], tip: 'Aap khud Sheet seedha kholkar badlen to bhi alert aayega; tab "Dekh liya" dabayein. Ye jaanch lagbhag 10 minute ke antar se kaam karti hai.', rel: ['a-sec-attack'] },
    { id: 'a-sec-site', a: A, cat: 'Suraksha', title: 'Website ki file badal jaye (GitHub) to kaise pata chalega?', kw: ['website badli', 'github', 'github file', 'file badal', 'website hack', 'baseline', 'website jaanch', 'site changed', 'website kharab', 'website nahi khul rahi', 'github password'],
      where: 'Suraksha tab -> Nigrani ki halat', steps: ['Suraksha tab me apni website ka link (https://naam.github.io/repo/) likhkar "Baseline banayein" dabayein. Ye abhi ki sahi files ka nishaan yaad kar leta hai.', 'Uske baad har ghante files jaanchi jati hain. Koi file badli (bina aapke upload kiye) to "Website ki file badal gayi" alert aata hai.', 'Aisa ho to turant "Staff panel band karein", GitHub -> Commits me dekhein kisne badla, galat commit "Revert" karein aur GitHub ka password badlein.', 'Aap khud nayi file upload karein to uske baad dobara "Baseline banayein" dabayein, warna alert aayega.'], tip: 'config.js, common.js, admin.js jaisi files ka badalna sabse khatarnak hai kyunki unse password chori ho sakta hai.', rel: ['a-sec-attack'] },
    { id: 'a-sec-lock', a: A, cat: 'Suraksha', title: 'Staff panel band ya khola kaise karein? Sab session kaise band karein?', kw: ['staff panel band', 'panel band', 'lock', 'lockdown', 'emergency', 'staff session band', 'sab logout', 'session band', 'staff panel dobara', 'kholna', 'staff ko rokna'],
      where: 'Suraksha tab', steps: ['"Staff panel abhi band karein" dabayein (dobara dabane par pakka). Ab koi staff login ya registration nahi kar sakta. Admin console chalta rehta hai.', '"Sab staff session band" se sabke purane link aur login khatam ho jate hain; staff ko ID aur password se dobara login karna padta hai.', '"Sab admin session band" se admin ke sab login band hote hain; aapko bhi dobara login karna hoga.', 'Dobara kholne ke liye "Staff panel dobara kholein" dabayein.'], tip: 'Ye button sirf aapko dikhte hain, staff ya public website par nahi.' },
    { id: 'a-sec-install', a: A, cat: 'Suraksha', title: 'Har ghante ki suraksha jaanch kaise chalu karein?', kw: ['a2zsecurityinstall', 'nigrani chalu', 'har ghante', 'trigger', 'watch', 'security install', 'suraksha chalu', 'suraksha install', 'test alert', 'alert mail nahi aayi'],
      where: 'Apps Script editor (ek baar) aur Suraksha tab', steps: ['Apps Script editor kholein, upar function list me "a2zSecurityInstall" chunein aur "Run" dabayein.', 'Google permission maange to "Allow" karein (aapki hi Sheet aur Drive ke liye).', 'Aapki Gmail par ek "Jaanch alert" mail aayegi. Na aaye to Spam dekhein.', 'Ab har ghante Sheet, sharing aur website ki jaanch apne-aap hogi. Suraksha tab me "chalu" likha dikhega.'], tip: 'Ye ek baar karna hota hai. Poori jankari guide ke Part K me hai.', rel: ['a-sec-what'] },
    { id: 'a-party-advance', a: A, cat: 'Paisa', title: 'Party ne advance diya to kaise likhein aur kitna bacha kaise dekhein?', kw: ['party advance', 'party ne advance', 'party ka advance', 'advance mila', 'party se advance', 'party advance bacha', 'kul bill', 'abhi bacha', 'party ka hisaab', 'party ledger', 'bill me se ghatana'],
      where: 'Party / Company tab', steps: ['"Party / Company" tab kholein. Us party ke card par "Advance mila" dabayein.', 'Rakam, tarikh aur note likhkar Save karein.', 'Tab ke upar "Party ka kul hisaab" table me har party ka Kul bill, Advance mila, Payment mila aur Abhi bacha (baaki) dikhta hai. Abhi bacha = Kul bill - Advance - Payment.', 'Abhi bacha minus ho to party ka advance abhi bacha hua hai (aage ke bill me katega). "Excel" se ye table download ho jati hai.'], tip: 'Advance kisi ek mahine ka nahi hota, isliye ye hisaab saare mahine milakar bante hain.' },
    { id: 'a-sahayak-ai', a: A, cat: 'A2Z Sahayak', title: 'A2Z Sahayak (AI) kya hai aur kaise use karein?', kw: ['ai', 'groq', 'sahayak', 'a2z sahayak', 'chatbot', 'ai se poochna', 'groq key', 'artificial'],
      where: 'Madad (Help) tab', steps: ['Madad tab me sawal likhkar "AI se poochhein" dabayein.', 'AI aapke business ka saar (party, staff, bill, baaki, advance) aur website ka manual padhkar jawab deta hai.', 'AI na chale to Apps Script ke Script Properties me GROQ_API_KEY jaanchein (guide ka Part Y).'], tip: 'AI ko aapke business ke naam aur rakam Groq ko jaate hain; password, OTP, phone, pata kabhi nahi jate. Staff ko AI sirf unke kaam ka jawab deta hai, rakam kabhi nahi.' },
    { id: 'a-agree', a: A, cat: 'Agreement', title: 'Agreement ke form (company, staff, labour, gaadi) kahan hain?', kw: ['agreement', 'anubandh', 'contract', 'ikrarnama', 'agreement form', 'labour joining', 'joining form', 'commission agreement', 'rent agreement', 'agreement print'],
      where: 'Admin > "Agreement / Forms" tab', steps: ['"Agreement / Forms" tab kholein. Chaaron agreement ke namoone dikhte hain.', '"PDF kholein / print" se print karein, ya "Word" se download karke apne naam aur rate bharein.', 'Company wale do agreement public site ke Terms page par, aur staff wale staff panel ke "Agreement / Forms" tab me bhi dikhte hain.'], tip: 'Ye namoone hain: vakeel se jaanch karwakar stamp paper par chhapwayein.' }
  ]);
})();
